/// The items below are pub(crate).
/// One command the palette can run.
#[derive(Clone, Debug, PartialEq)]
struct CommandEntry {
    pub name: &'static str,
    pub binding: Option<&'static str>,
    pub command: kate_core::Command,
}

/// The items below are pub(crate).
/// The fixed list: Save, Undo, Redo, Select All, Complete Word, Indent, Unindent, Reload, Select Next Occurrence, Toggle Fold, Add Cursor Below, Add Cursor Above.
fn command_entries() -> Vec<CommandEntry>
/// Entries whose name matches `query`, best first, as rows with the binding as detail.
fn command_rows(query: &str, limit: usize) -> Vec<PaletteRow>
